import java.util.Scanner;

public class Prepare {

    public static void main(String[] args) {
        Scanner scn = new Scanner(System.in);
        int inputNumber = scn.nextInt();
        String inputStr = scn.next();
        int maxRun = 0;
        int runLength = 0;
        int underscoreCountTotal = 0;
        boolean insideParen = false;
        boolean lastCharLetterFlag = false;

        for (int i = 0; i < inputStr.length(); i++) {
            char ch = inputStr.charAt(i);
            if ((ch > 96 && ch < 123) || (ch > 64 && ch < 91)) {
                if (insideParen && !lastCharLetterFlag)
                    underscoreCountTotal++;
                if (!insideParen)
                    runLength++;
                if (runLength > maxRun)
                    maxRun = runLength;
                lastCharLetterFlag = true;
            } else if (ch == '_') {
                lastCharLetterFlag = false;
                if (runLength > maxRun)
                    maxRun = runLength;
                runLength = 0;
            } else if (ch == '(') {
                lastCharLetterFlag = false;
                insideParen = true;
                if (runLength > maxRun)
                    maxRun = runLength;
                runLength = 0;
            } else if (ch == ')') {
                insideParen = false;
                lastCharLetterFlag = false;
                if (runLength > maxRun)
                    maxRun = runLength;
                runLength = 0;
            }
        }
        System.out.println(maxRun + " " + underscoreCountTotal);
        scn.close();
    }
}
